// DefaultExcludeDirs are dependency, build-output and cache directories skipped by default
// (Options.NoDefaultExcludes / .crev.yaml default_excludes: false turns this off).
var DefaultExcludeDirs = []string{
	".git", ".hg", ".svn", "node_modules", "vendor", "bower_components", "jspm_packages", "__pycache__",
	".nuxt", ".next", ".output", ".svelte-kit", ".angular", ".astro", ".vercel", ".netlify", ".turbo", ".cache",
	".parcel-cache", ".vite", ".docusaurus", ".expo", "dist", "build", "out", "target", ".gradle", "coverage",
	".nyc_output", ".venv", "venv", ".tox", ".nox", ".mypy_cache", ".pytest_cache", ".ruff_cache", ".terraform",
	".terragrunt-cache", ".serverless", ".dart_tool", "Pods", "DerivedData", ".idea", ".vs", "__generated__",
	".crev", // crev state: reports, runs, AI handoff, user rules (validated by `crev rules validate`, not linted)
}

// dotnetOnlyDirs are excluded only next to a .NET project file (bin/ is a normal source dir elsewhere).
var dotnetOnlyDirs = map[string]bool{"bin": true, "obj": true}

// DefaultExcludeFiles are generated or vendored artefacts and lockfiles. Lockfiles are excluded from
// rule review only: version detection reads them directly from disk (internal/versions).
var DefaultExcludeFiles = []string{
	"*.min.js", "*.min.mjs", "*.min.css", "*.map", "*.bundle.js", "*.chunk.js",
	"*.pb.go", "*.pb.gw.go", "*_grpc.pb.go", "*.pb.validate.go", "*_pb2.py", "*_pb2.pyi", "*_pb2_grpc.py", "*_pb.js", "*_pb.d.ts",
	"*_grpc_pb.js", "*.pb.ts", "*.pb.swift", "*.pb.cc", "*.pb.h", "*.generated.*", "*.gen.go", "*_gen.go", "zz_generated.*",
	"graphql-env.d.ts",
	"package-lock.json", "npm-shrinkwrap.json", "yarn.lock", "pnpm-lock.yaml", "bun.lock", "bun.lockb", "composer.lock",
	"go.sum", "go.work.sum", "poetry.lock", "Pipfile.lock", "uv.lock", "pdm.lock", "gradle.lockfile", "buildscript-gradle.lockfile",
	".terraform.lock.hcl", "Cargo.lock", "Gemfile.lock", "mix.lock", "packages.lock.json",
}

var generatedHeader = regexp.MustCompile(`(?m)(@generated\b|^\s*(//|#|/\*|\*|--)?\s*Code generated .* DO NOT EDIT\.?|<auto-generated|^\s*(//|#)\s*DO NOT EDIT[.!]? ?(This file|Generated|Automatically)|^//\s*Generated by [\w@/.-]+(\s*$|\.?\s*\S{0,3}\s*DO NOT (MODIFY|EDIT))|^\s*(//|#|/\*|\*)\s*This file (is|was|has been) (auto-?generated|automatically generated|generated automatically)\b)`)

// IsGeneratedSource reports whether the first 2 KiB carry a generated-code marker
// ("Code generated ... DO NOT EDIT." per https://go.dev/s/generatedcode, "@generated", "<auto-generated>").
func IsGeneratedSource(src []byte) bool {
	if len(src) > 2048 {
		src = src[:2048]
	}
	return generatedHeader.Match(src)
}

// IsMinifiedSource reports whether a JavaScript/CSS file is a minified bundle checked in under an
// ordinary name (no .min. suffix): at least 10 KB with lines averaging 300+ bytes or one line of
// 20 000+ bytes. Rules on such files report the bundler's output, not code anyone edits.
var sourceMapRef = regexp.MustCompile(`(?m)^\s*(//|/\*)[#@] sourceMappingURL=\S+\s*(\*/)?\s*$`)

func IsMinifiedSource(rel string, src []byte) bool {
	switch strings.ToLower(path.Ext(rel)) {
	case ".js", ".mjs", ".cjs", ".css":
	default:
		return false
	}
	// bundler/compiler output ends with a source-map reference (//# sourceMappingURL=...)
	tail := src
	if len(tail) > 512 {
		tail = tail[len(tail)-512:]
	}
	if sourceMapRef.Match(tail) {
		return true
	}
	if len(src) < 10*1024 {
		return false
	}
	lines, longest, cur := 1, 0, 0
	for _, c := range src {
		if c == '\n' {
			lines++
			if cur > longest {
				longest = cur
			}
			cur = 0
			continue
		}
		cur++
	}
	if cur > longest {
		longest = cur
	}
	return len(src)/lines >= 300 || longest >= 20000
}

func defaultExcludedDir(abs, name string) bool {
	if slices.Contains(DefaultExcludeDirs, name) {
		return true
	}
	if dotnetOnlyDirs[name] {
		ents, _ := os.ReadDir(filepath.Dir(abs))
		for _, e := range ents {
			switch strings.ToLower(filepath.Ext(e.Name())) {
			case ".csproj", ".fsproj", ".vbproj", ".sln":
				return true
			}
		}
	}
	return false
}

func defaultExcludedFile(name string) bool {
	for _, g := range DefaultExcludeFiles {
		if ok, _ := path.Match(g, name); ok {
			return true
		}
	}
	return false
}

// ---- .gitignore ------------------------------------------------------------------------------

type ignorePattern struct {
	re      *regexp.Regexp
	negate  bool
	dirOnly bool
}

// gitIgnore holds patterns per directory (repo-relative, "." = root), in git precedence order:
// .git/info/exclude, then each .gitignore from the root down; the last matching pattern wins.
type gitIgnore struct {
	root  string
	byDir map[string][]ignorePattern
}

func newGitIgnore(root string) *gitIgnore {
	g := &gitIgnore{root: root, byDir: map[string][]ignorePattern{}}
	if b, err := os.ReadFile(filepath.Join(root, ".git", "info", "exclude")); err == nil {
		g.byDir["."] = append(g.byDir["."], parseGitignore(b)...)
	}
	return g
}

// load reads <dir>/.gitignore (called when the walk enters dir).
func (g *gitIgnore) load(dirRel string) {
	if b, err := os.ReadFile(filepath.Join(g.root, filepath.FromSlash(dirRel), ".gitignore")); err == nil {
		g.byDir[dirRel] = append(g.byDir[dirRel], parseGitignore(b)...)
	}
}

// Ignored reports whether repo-relative rel (slash separated) is ignored.
func (g *gitIgnore) Ignored(rel string, isDir bool) bool {
	ignored := false
	dirs := []string{"."}
	parts := strings.Split(rel, "/")
	for i := 1; i < len(parts); i++ {
		dirs = append(dirs, strings.Join(parts[:i], "/"))
	}
	for _, d := range dirs {
		pats := g.byDir[d]
		if len(pats) == 0 {
			continue
		}
		sub := rel
		if d != "." {
			sub = strings.TrimPrefix(rel, d+"/")
		}
		for _, p := range pats {
			if p.dirOnly && !isDir {
				continue
			}
			if p.re.MatchString(sub) {
				ignored = !p.negate
			}
		}
	}
	return ignored
}

func parseGitignore(b []byte) []ignorePattern {
	var out []ignorePattern
	sc := bufio.NewScanner(bytes.NewReader(b))
	for sc.Scan() {
		line := strings.TrimSuffix(sc.Text(), "\r")
		// trailing spaces are ignored unless escaped with a backslash
		for strings.HasSuffix(line, " ") && !strings.HasSuffix(line, "\\ ") {
			line = line[:len(line)-1]
		}
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		p := ignorePattern{}
		if strings.HasPrefix(line, "!") {
			p.negate, line = true, line[1:]
		} else if strings.HasPrefix(line, `\!`) || strings.HasPrefix(line, `\#`) {
			line = line[1:]
		}
		if l, ok := strings.CutSuffix(line, "/"); ok {
			p.dirOnly, line = true, l
		}
		anchored := strings.Contains(line, "/")
		line = strings.TrimPrefix(line, "/")
		if line == "" {
			continue
		}
		re, err := regexp.Compile(globToRegexp(line, anchored))
		if err != nil {
			continue
		}
		p.re = re
		out = append(out, p)
	}
	return out
}

func globToRegexp(pat string, anchored bool) string {
	var b strings.Builder
	if anchored {
		b.WriteString("^")
	} else {
		b.WriteString("^(?:.*/)?")
	}
	for i := 0; i < len(pat); i++ {
		c := pat[i]
		switch {
		case c == '*' && strings.HasPrefix(pat[i:], "**/"):
			b.WriteString("(?:.*/)?")
			i += 2
		case c == '*' && strings.HasPrefix(pat[i:], "**") && i+2 == len(pat):
			b.WriteString(".*")
			i++
		case c == '*':
			b.WriteString("[^/]*")
		case c == '?':
			b.WriteString("[^/]")
		case c == '\\' && i+1 < len(pat):
			i++
			b.WriteString(regexp.QuoteMeta(string(pat[i])))
		case c == '[':
			j := strings.IndexByte(pat[i+1:], ']')
			if j < 0 {
				b.WriteString(`\[`)
				continue
			}
			class := pat[i+1 : i+1+j]
			if strings.HasPrefix(class, "!") {
				class = "^" + class[1:]
			}
			b.WriteString("[" + strings.ReplaceAll(class, `\`, `\\`) + "]")
			i += j + 1
		default:
			b.WriteString(regexp.QuoteMeta(string(c)))
		}
	}
	// a pattern matching a directory also covers everything below it
	b.WriteString("(?:/.*)?$")
	return b.String()
}

// PathFilter applies the scan's exclusions (ignore globs, default excluded directories,
// .gitignore) for walkers outside the rule engine, e.g. SCA lockfile discovery. Default file
// excludes (lockfiles, minified files) are not applied: callers choose their own files.
// Directories must be offered in walk order (parents first) so nested .gitignore files load.
func PathFilter(root string, ignore []string, noGitignore, noDefaultExcludes bool) func(rel string, isDir bool) bool {
	globs := append(append([]string{}, defaultIgnore...), ignore...)
	var gi *gitIgnore
	if !noGitignore {
		gi = newGitIgnore(root)
	}
	return func(rel string, isDir bool) bool {
		if isDir {
			if rel == "." || rel == "" {
				if gi != nil {
					gi.load(".")
				}
				return false
			}
			if ignored(globs, rel+"/") || (!noDefaultExcludes && defaultExcludedDir(filepath.Join(root, rel), filepath.Base(rel))) || (gi != nil && gi.Ignored(rel, true)) {
				return true
			}
			if gi != nil {
				gi.load(rel)
			}
			return false
		}
		return ignored(globs, rel) || (gi != nil && gi.Ignored(rel, false))
	}
}
